        guard let data = Data(base64Encoded: encoded, options: .ignoreUnknownCharacters),
              data.count == ids.count * bytesPerGlyph else {
            preconditionFailure("Invalid generated eye glyph catalog")
        }
        return data
    }()

    public static func bitmap(for id: String) -> Data? {
        guard let index = indexByID[id] else { return nil }
        let start = index * bytesPerGlyph
        return packed.subdata(in: start..<(start + bytesPerGlyph))
    }

    public static func pixelIsSet(in bitmap: Data, x: Int, y: Int) -> Bool {
        guard bitmap.count == bytesPerGlyph,
              (0..<width).contains(x),
              (0..<height).contains(y) else { return false }
        let offset = y * rowBytes + x / 8
        return bitmap[offset] & (0x80 >> UInt8(x & 7)) != 0
    }
}
